/**
 * Find one object by its page slug.
 *
 * @param string $slug Object page slug.
 * @return array<string, mixed>|null
 */
function barella_object_by_slug( $slug ) {
	foreach ( barella_objects_data() as $barella_object ) {
		if ( $barella_object['slug'] === $slug ) {
			return $barella_object;
		}
	}
	return null;
}
